1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = { itemType: string; amount: number };
9	
10	export type Incident = { cause: string; damages: Damage[] };
11	
12	export type QuoteStep = { op: "quote"; items: Item[] };
13	
14	// `policy` is the zero-based index of the quote step that created the policy.
15	export type ClaimStep = { op: "claim"; policy: number; incident: Incident };
16	
17	export type Step = QuoteStep | ClaimStep;
18	
19	export type Customer = { yearsWithMHPCO: number };
20	
21	export type Scenario = {
22	  customer: Customer;
23	  steps: Step[];
24	};
25	
26	export type QuoteResult = { premium: number };
27	
28	export type ClaimResult = { payout: number; remainingCap: number };
29	
30	export type StepResult = QuoteResult | ClaimResult;
31	
32	export type ScenarioResult = { results: StepResult[] };
33	
34	const BASE_PRICE_BY_TYPE: Record<string, number> = {
35	  sword: 100,
36	  amulet: 60,
37	  staff: 80,
38	  potion: 40,
39	  rune: 25,
40	  moonstone: 25,
41	};
42	
43	// What an item is insured for, as opposed to what it costs to insure.
44	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
45	  sword: 1000,
46	  amulet: 600,
47	  staff: 800,
48	  potion: 400,
49	  rune: 250,
50	  moonstone: 250,
51	};
52	
53	const FIRST_INSURANCE_MULTIPLIER = 1.1;
54	const CONTRACT_FEE = 5;
55	
56	const BUILDING_BLOCK_SIZE = 3;
57	const BUILDING_BLOCK_PRICE = 60;
58	
59	const CURSED_SURCHARGE_RATE = 0.5;
60	const HIGH_ENCHANTMENT_LEVEL = 5;
61	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
62	
63	// Each surcharge adds a percentage of the base price when its condition holds.
64	// Rates add together, so a cursed and highly enchanted item pays 1 + 0.5 + 0.3.
65	const RISK_SURCHARGES: { appliesTo: (item: Item) => boolean; rate: number }[] = [
66	  { appliesTo: (item) => item.cursed === true, rate: CURSED_SURCHARGE_RATE },
67	  {
68	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
69	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
70	  },
71	];
72	
73	const totalSurchargeRateFor = (item: Item): number =>
74	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
75	    (total, surcharge) => total + surcharge.rate,
76	    0,
77	  );
78	
79	// Risk surcharges apply per item, before the contract-level multiplier and fee.
80	const riskAdjustedPriceOfItem = (item: Item): number =>
81	  BASE_PRICE_BY_TYPE[item.type] * (1 + totalSurchargeRateFor(item));
82	
83	const sumOfIndividualPrices = (items: Item[]): number =>
84	  items.reduce((total, item) => total + riskAdjustedPriceOfItem(item), 0);
85	
86	// "Alike" in the price list means same type — material and enchantment do not
87	// affect whether components group into a building block.
88	const groupByType = (items: Item[]): Item[][] => [
89	  ...items
90	    .reduce(
91	      (groups, item) =>
92	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
93	      new Map<string, Item[]>(),
94	    )
95	    .values(),
96	];
97	
98	// Every three alike components form a building block priced at 60 G; the
99	// remainder of the group is priced individually.
100	const priceOfAlikeGroup = (group: Item[]): number => {
101	  const completeBlocks = Math.floor(group.length / BUILDING_BLOCK_SIZE);
102	  const itemsInBlocks = completeBlocks * BUILDING_BLOCK_SIZE;
103	
104	  return (
105	    completeBlocks * BUILDING_BLOCK_PRICE +
106	    sumOfIndividualPrices(group.slice(itemsInBlocks))
107	  );
108	};
109	
110	// The basis the premium is charged on: price-list figures plus per-item risk
111	// surcharges, before any contract-level multiplier or fee. Distinct from
112	// coverSumOf, which is what those same items are insured *for*.
113	const premiumBasisOf = (items: Item[]): number =>
114	  groupByType(items).reduce((total, group) => total + priceOfAlikeGroup(group), 0);
115	
116	const LOYALTY_YEARS = 2;
117	const LOYALTY_DISCOUNT_RATE = 0.2;
118	
119	const loyaltyMultiplierFor = (customer: Customer): number =>
120	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? 1 - LOYALTY_DISCOUNT_RATE : 1;
121	
122	const REPEAT_CONTRACT_DISCOUNT_RATE = 0.15;
123	
124	// A first insurance carries an assessment surcharge; every later contract
125	// earns the repeat-customer discount instead.
126	const repeatCustomerMultiplierFor = (isFirstContract: boolean): number =>
127	  isFirstContract ? FIRST_INSURANCE_MULTIPLIER : 1 - REPEAT_CONTRACT_DISCOUNT_RATE;
128	
129	// Customer-dependent factors that scale the whole contract, as opposed to the
130	// per-item risk surcharges already folded into the insured value.
131	const contractMultiplierFor = (
132	  customer: Customer,
133	  isFirstContract: boolean,
134	): number =>
135	  loyaltyMultiplierFor(customer) * repeatCustomerMultiplierFor(isFirstContract);
136	
137	// Amounts are rounded up, in MHPCO's favor. The product is first snapped to
138	// six decimals so IEEE754 noise (100 × 1.1 = 110.00000000000001) does not
139	// push an exact amount to the next whole G.
140	const roundedUpInMHPCOsFavor = (amount: number): number =>
141	  Math.ceil(Number(amount.toFixed(6)));
142	
143	const resultOfQuoteStep = (
144	  step: QuoteStep,
145	  customer: Customer,
146	  isFirstContract: boolean,
147	): QuoteResult => ({
148	  premium:
149	    roundedUpInMHPCOsFavor(
150	      premiumBasisOf(step.items) * contractMultiplierFor(customer, isFirstContract),
151	    ) + CONTRACT_FEE,
152	});
153	
154	const DEDUCTIBLE = 100;
155	const CAP_FACTOR = 2;
156	
157	// What the items are insured for, as opposed to what they cost to insure.
158	const coverSumOf = (items: Item[]): number =>
159	  items.reduce((total, item) => total + INSURANCE_VALUE_BY_TYPE[item.type], 0);
160	
161	// A claim names the quote step that created its policy. Resolving it by
162	// narrowing rather than casting means a mis-aimed index fails here, with the
163	// offending index in hand, instead of silently yielding NaN downstream.
164	const insuredItemsOf = (policyIndex: number, steps: Step[]): Item[] => {
165	  const policy = steps[policyIndex];
166	
167	  if (policy?.op !== "quote") {
168	    throw new Error(`Step ${policyIndex} is not a quote step`);
169	  }
170	
171	  return policy.items;
172	};
173	
174	const FRAGILE_ENCHANTMENT_LEVEL = 8;
175	const FRAGILE_REIMBURSEMENT_RATE = 0.5;
176	
177	const FULL_REIMBURSEMENT_RATE = 1;
178	
179	const DRAGON_MATERIAL = "dragon";
180	
181	// Order is significant: the first rule that applies sets the rate, so dragon
182	// material overrides the high-enchantment halving. Add new rules at the
183	// position matching their specificity, not at the end. Anything no rule claims
184	// is reimbursed in full.
185	const REIMBURSEMENT_RULES_MOST_SPECIFIC_FIRST: {
186	  appliesTo: (item: Item) => boolean;
187	  rate: number;
188	}[] = [
189	  {
190	    appliesTo: (item) => item.material === DRAGON_MATERIAL,
191	    rate: FULL_REIMBURSEMENT_RATE,
192	  },
193	  {
194	    appliesTo: (item) => (item.enchantment ?? 0) >= FRAGILE_ENCHANTMENT_LEVEL,
195	    rate: FRAGILE_REIMBURSEMENT_RATE,
196	  },
197	];
198	
199	const reimbursementRateFor = (item: Item): number =>
200	  REIMBURSEMENT_RULES_MOST_SPECIFIC_FIRST.find(({ appliesTo }) => appliesTo(item))
201	    ?.rate ?? FULL_REIMBURSEMENT_RATE;
202	
203	// A damage names the type of the item it befell. A damage to something not on
204	// the policy has no insured item to rate, and is reimbursed in full.
205	const reimbursementRateForDamageTo = (
206	  itemType: string,
207	  insured: Item[],
208	): number => {
209	  const damagedItem = insured.find(({ type }) => type === itemType);
210	
211	  return damagedItem ? reimbursementRateFor(damagedItem) : FULL_REIMBURSEMENT_RATE;
212	};
213	
214	const totalReimbursableOf = (incident: Incident, insured: Item[]): number =>
215	  incident.damages.reduce(
216	    (total, { itemType, amount }) =>
217	      total + amount * reimbursementRateForDamageTo(itemType, insured),
218	    0,
219	  );
220	
221	// The customer bears the deductible, and never the other way round: a damage
222	// smaller than the deductible pays nothing rather than billing the customer.
223	const afterDeductible = (reimbursable: number): number =>
224	  Math.max(0, reimbursable - DEDUCTIBLE);
225	
226	// The cap is the ceiling on what a policy pays, not on what it reimburses:
227	// it is applied last, after the deductible has been borne.
228	const capPolicyPayout = (amount: number, cap: number): number =>
229	  Math.min(cap, amount);
230	
231	const payoutCapOf = (insured: Item[]): number =>
232	  CAP_FACTOR * coverSumOf(insured);
233	
234	// The cap belongs to the policy, not the claim: successive claims draw down a
235	// shared balance, so the caller supplies what earlier claims have left.
236	const resultOfClaimStep = (
237	  step: ClaimStep,
238	  steps: Step[],
239	  capRemaining: number,
240	): ClaimResult => {
241	  const insured = insuredItemsOf(step.policy, steps);
242	  const payout = capPolicyPayout(
243	    afterDeductible(totalReimbursableOf(step.incident, insured)),
244	    capRemaining,
245	  );
246	
247	  return { payout, remainingCap: capRemaining - payout };
248	};
249	
250	// It is contracts that count, not steps: a quote preceded only by claim steps
251	// is still the customer's first contract. Claims are therefore not counted.
252	const isFirstContractAt = (stepIndex: number, steps: Step[]): boolean =>
253	  !steps.slice(0, stepIndex).some(({ op }) => op === "quote");
254	
255	// What running the scenario carries from one step to the next: the results so
256	// far, and how much of each policy's cap its earlier claims have left. A policy
257	// absent from the ledger has not been claimed against yet and still has its
258	// full cap; policies draw down independently of one another.
259	type ScenarioProgress = {
260	  results: StepResult[];
261	  capRemainingByPolicy: Map<number, number>;
262	};
263	
264	const EMPTY_PROGRESS: ScenarioProgress = {
265	  results: [],
266	  capRemainingByPolicy: new Map(),
267	};
268	
269	const withResult = (
270	  progress: ScenarioProgress,
271	  result: StepResult,
272	): ScenarioProgress => ({
273	  ...progress,
274	  results: [...progress.results, result],
275	});
276	
277	// A quote leaves the ledger untouched: caps are drawn down by claims alone.
278	const progressAfterQuoteStep = (
279	  step: QuoteStep,
280	  index: number,
281	  scenario: Scenario,
282	  progress: ScenarioProgress,
283	): ScenarioProgress =>
284	  withResult(
285	    progress,
286	    resultOfQuoteStep(
287	      step,
288	      scenario.customer,
289	      isFirstContractAt(index, scenario.steps),
290	    ),
291	  );
292	
293	// A claim is the only step that both reads and advances the ledger, so it is
294	// the only one that returns a new one.
295	const progressAfterClaimStep = (
296	  step: ClaimStep,
297	  steps: Step[],
298	  progress: ScenarioProgress,
299	): ScenarioProgress => {
300	  const { capRemainingByPolicy } = progress;
301	  const capRemaining =
302	    capRemainingByPolicy.get(step.policy) ??
303	    payoutCapOf(insuredItemsOf(step.policy, steps));
304	  const result = resultOfClaimStep(step, steps, capRemaining);
305	
306	  return withResult(
307	    {
308	      ...progress,
309	      capRemainingByPolicy: new Map(capRemainingByPolicy).set(
310	        step.policy,
311	        result.remainingCap,
312	      ),
313	    },
314	    result,
315	  );
316	};
317	
318	// Steps are folded rather than mapped: a claim's payout depends on what earlier
319	// claims on the same policy have already drawn, so the steps are not
320	// independent and the carried ledger belongs in the signature, not in a closure.
321	export const runScenario = (scenario: Scenario): ScenarioResult => {
322	  const { results } = scenario.steps.reduce<ScenarioProgress>(
323	    (progress, step, index) =>
324	      step.op === "quote"
325	        ? progressAfterQuoteStep(step, index, scenario, progress)
326	        : progressAfterClaimStep(step, scenario.steps, progress),
327	    EMPTY_PROGRESS,
328	  );
329	
330	  return { results };
331	};
